import uuid

from dynamodb.entity.todo.todo_entity import TodoEntity
from dynamodb.entity.todo.todo_entity_repo import TodoEntityRepo, TodoQueryResponse


class TodoEntityService:

    def __init__(self, repo: TodoEntityRepo):
        self.repo = repo

    def put_todo(self, todo: TodoEntity) -> TodoEntity:
        todo_dict = todo.to_dict()
        todo = TodoEntity.from_dict(todo_dict)
        todo.sk = f"{TodoEntity.entity_type.value}#{str(uuid.uuid4())}"
        self.repo.put_todo(todo=todo)
        return todo

    def find_all_todo_by_list_id(self, list_id: str) -> TodoQueryResponse:
        return self.repo.find_all_todo_by_list_id(list_id=list_id)

    def update_todo(self, list_id: str, todo_id: str, updates: dict):
        self.repo.update_todo(list_id=list_id, todo_id=todo_id, updates=updates)
